//! Replays `testdata/port/ingest/paperless-run.json`, generated by the real Go
//! `TestPortPaperlessRunContract`: `Run` / `importOne` / `selectDocuments` /
//! `loadLookups` / `WriteMigrationReport` against a loopback fake Paperless API
//! (scripted routes), the real Rust pipeline and a real vault, archive and
//! SQLite store. Stats, progress/stderr/log output, the requests the server
//! saw, both file trees, the store rows and the written report must match Go.
#![cfg(unix)]

use base64::Engine as _;
use regex::Regex;
use serde_json::{Value, json};
use sha2::{Digest, Sha256};
use std::collections::BTreeMap;
use std::io::{BufRead, BufReader, Read, Write};
use std::net::{TcpListener, TcpStream};
use std::path::Path;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Mutex};
use symdesk_ingest::extract::Extraction;
use symdesk_ingest::ocr::Context;
use symdesk_ingest::paperless_run::{Options, Sink, run, write_migration_report};
use symdesk_ingest::pipeline::{Engine, Pipeline};
use symdesk_ingest::writer::NoteWriter;
use symdesk_ingest::Store;

/// `TMPDIR` is process-global; scenarios run one at a time.
static ENV_LOCK: Mutex<()> = Mutex::new(());

fn fixture() -> Value {
    let f: Value = serde_json::from_slice(
        &std::fs::read(
            Path::new(env!("CARGO_MANIFEST_DIR"))
                .join("../../testdata/port/ingest/paperless-run.json"),
        )
        .unwrap(),
    )
    .unwrap();
    assert_eq!(f["schema_version"], 1);
    f
}

struct RunEngine {
    fail_text: bool,
}

impl Engine for RunEngine {
    fn extract(&self, _ctx: &Context, path: &str, kind: &str) -> Result<Extraction, String> {
        let bytes = std::fs::read(path).unwrap_or_default();
        if self.fail_text && bytes.windows(6).any(|w| w == b"FAILME") {
            return Err("extract text failed: scripted".to_owned());
        }
        Ok(Extraction {
            text: format!("extracted {} bytes", bytes.len()),
            mime: kind.to_owned(),
            engine: "fake".to_owned(),
            language: String::new(),
        })
    }
}

#[derive(Clone)]
struct Route {
    path: String,
    page: String,
    status: u16,
    headers: BTreeMap<String, String>,
    body: String,
    body_b64: String,
}

fn routes_from(value: &Value) -> Vec<Route> {
    value
        .as_array()
        .map(|list| {
            list.iter()
                .map(|r| Route {
                    path: r["path"].as_str().unwrap().to_owned(),
                    page: r["page"].as_str().unwrap_or("").to_owned(),
                    status: r["status"].as_u64().unwrap() as u16,
                    headers: r["headers"]
                        .as_object()
                        .map(|m| {
                            m.iter()
                                .map(|(k, v)| (k.clone(), v.as_str().unwrap().to_owned()))
                                .collect()
                        })
                        .unwrap_or_default(),
                    body: r["body"].as_str().unwrap_or("").to_owned(),
                    body_b64: r["body_b64"].as_str().unwrap_or("").to_owned(),
                })
                .collect()
        })
        .unwrap_or_default()
}

fn reason(status: u16) -> &'static str {
    match status {
        200 => "OK",
        401 => "Unauthorized",
        404 => "Not Found",
        500 => "Internal Server Error",
        _ => "Status",
    }
}

struct Server {
    host: String,
    routes: Arc<Mutex<Vec<Route>>>,
    requests: Arc<Mutex<Vec<Value>>>,
    stop: Arc<AtomicBool>,
    thread: Option<std::thread::JoinHandle<()>>,
}

impl Server {
    fn start(routes: Vec<Route>) -> Self {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let host = listener.local_addr().unwrap().to_string();
        let routes = Arc::new(Mutex::new(routes));
        let requests = Arc::new(Mutex::new(Vec::new()));
        let stop = Arc::new(AtomicBool::new(false));
        let (r, q, s, h) = (
            Arc::clone(&routes),
            Arc::clone(&requests),
            Arc::clone(&stop),
            host.clone(),
        );
        let thread = std::thread::spawn(move || {
            for stream in listener.incoming() {
                if s.load(Ordering::SeqCst) {
                    return;
                }
                if let Ok(stream) = stream {
                    handle(stream, &r, &q, &h);
                }
            }
        });
        Self {
            host,
            routes,
            requests,
            stop,
            thread: Some(thread),
        }
    }

    fn finish(mut self) -> Vec<Value> {
        self.stop.store(true, Ordering::SeqCst);
        let _ = TcpStream::connect(&self.host);
        if let Some(t) = self.thread.take() {
            t.join().unwrap();
        }
        self.requests.lock().unwrap().clone()
    }
}

fn handle(mut stream: TcpStream, routes: &Mutex<Vec<Route>>, seen: &Mutex<Vec<Value>>, host: &str) {
    let mut reader = BufReader::new(stream.try_clone().unwrap());
    let mut first = String::new();
    if reader.read_line(&mut first).unwrap_or(0) == 0 {
        return;
    }
    let mut parts = first.split_whitespace();
    let (method, target) = (
        parts.next().unwrap_or("").to_owned(),
        parts.next().unwrap_or("").to_owned(),
    );
    let (mut auth, mut length) = (String::new(), 0usize);
    loop {
        let mut line = String::new();
        reader.read_line(&mut line).unwrap();
        let line = line.trim_end();
        if line.is_empty() {
            break;
        }
        if let Some((k, v)) = line.split_once(':') {
            match k.to_ascii_lowercase().as_str() {
                "authorization" => auth = v.trim().to_owned(),
                "content-length" => length = v.trim().parse().unwrap_or(0),
                _ => {}
            }
        }
    }
    let mut body = vec![0u8; length];
    let _ = reader.read_exact(&mut body);
    let (path, query) = target.split_once('?').unwrap_or((target.as_str(), ""));
    seen.lock().unwrap().push(json!({
        "method": method, "path": path, "query": query, "auth": auth
    }));
    let page = query
        .split('&')
        .find_map(|kv| kv.strip_prefix("page="))
        .unwrap_or("");
    let route = routes
        .lock()
        .unwrap()
        .iter()
        .rev()
        .find(|r| r.path == path && r.page == page)
        .cloned();
    let Some(route) = route else {
        let _ = stream.write_all(
            b"HTTP/1.1 404 Not Found\r\nContent-Length: 0\r\nConnection: close\r\n\r\n",
        );
        return;
    };
    let payload = if route.body_b64.is_empty() {
        route
            .body
            .replace("$BASE", &format!("http://{host}"))
            .into_bytes()
    } else {
        base64::engine::general_purpose::STANDARD
            .decode(&route.body_b64)
            .unwrap()
    };
    let mut head = format!(
        "HTTP/1.1 {} {}\r\nContent-Length: {}\r\nConnection: close\r\n",
        route.status,
        reason(route.status),
        payload.len()
    );
    for (k, v) in &route.headers {
        head.push_str(&format!("{k}: {v}\r\n"));
    }
    head.push_str("\r\n");
    let _ = stream.write_all(head.as_bytes());
    let _ = stream.write_all(&payload);
    let _ = stream.flush();
}

fn sorted_lines(text: &str) -> Vec<String> {
    let trimmed = text.trim_end_matches('\n');
    if text.is_empty() {
        return Vec::new();
    }
    trimmed.split('\n').map(str::to_owned).collect()
}

struct Norm {
    root: String,
    host: String,
    run_id: Regex,
    tmp: Regex,
    now: Regex,
    eta: Regex,
}

impl Norm {
    fn apply(&self, s: &str) -> String {
        let s = s.replace(&self.root, "<ROOT>").replace(&self.host, "<HOST>");
        let s = self.run_id.replace_all(&s, "paperless-<RUN>").into_owned();
        self.tmp.replace_all(&s, "<TMP>").into_owned()
    }
}

fn snapshot(root: &Path, sub: &str, norm: &Norm) -> Vec<Value> {
    let base = root.join(sub);
    let mut out = Vec::new();
    if std::fs::symlink_metadata(&base).is_err() {
        return out;
    }
    fn walk(dir: &Path, root: &Path, norm: &Norm, out: &mut Vec<Value>) {
        let mut entries: Vec<_> = std::fs::read_dir(dir)
            .unwrap()
            .map(|e| e.unwrap().path())
            .collect();
        entries.sort();
        for path in entries {
            let rel = path
                .strip_prefix(root)
                .unwrap()
                .to_string_lossy()
                .into_owned();
            if path.is_dir() {
                out.push(json!({"path": rel, "type": "dir"}));
                walk(&path, root, norm, out);
            } else {
                let bytes = std::fs::read(&path).unwrap();
                let name = path.to_string_lossy();
                if name.ends_with(".md") || name.ends_with(".json") {
                    let text = norm.apply(&String::from_utf8_lossy(&bytes));
                    let text = norm.now.replace_all(&text, "ingested_at: <NOW>").into_owned();
                    out.push(json!({"path": rel, "type": "file", "text": text}));
                } else {
                    let hash: String = Sha256::digest(&bytes)
                        .iter()
                        .map(|b| format!("{b:02x}"))
                        .collect();
                    out.push(json!({"path": rel, "type": "file", "sha256": hash}));
                }
            }
        }
    }
    out.push(json!({"path": sub, "type": "dir"}));
    walk(&base, root, norm, &mut out);
    out.sort_by(|a, b| a["path"].as_str().cmp(&b["path"].as_str()));
    out
}

fn dump_tables(db: &Path, norm: &Norm, unordered: bool) -> Value {
    let conn = rusqlite::Connection::open(db).unwrap();
    let mut out = serde_json::Map::new();
    for table in ["documents", "jobs", "paperless_import_state"] {
        let mut stmt = conn
            .prepare(&format!("SELECT * FROM {table} ORDER BY 1"))
            .unwrap();
        let cols: Vec<String> = stmt.column_names().iter().map(|c| (*c).to_owned()).collect();
        let rows = stmt
            .query_map([], |row| {
                let mut map = serde_json::Map::new();
                for (i, c) in cols.iter().enumerate() {
                    if c.ends_with("_at") || c == "updated" || c == "created" {
                        continue;
                    }
                    let value = match row.get_ref(i)? {
                        rusqlite::types::ValueRef::Null => Value::Null,
                        rusqlite::types::ValueRef::Integer(n) => json!(n),
                        rusqlite::types::ValueRef::Real(f) => json!(f),
                        rusqlite::types::ValueRef::Text(t) => {
                            json!(norm.apply(&String::from_utf8_lossy(t)))
                        }
                        rusqlite::types::ValueRef::Blob(b) => {
                            json!(norm.apply(&String::from_utf8_lossy(b)))
                        }
                    };
                    map.insert(c.clone(), value);
                }
                if unordered {
                    map.remove("id");
                    map.remove("document_id");
                }
                Ok(Value::Object(map))
            })
            .unwrap();
        let mut list: Vec<Value> = rows.map(Result::unwrap).collect();
        if unordered {
            list.sort_by_key(|v| {
                serde_json::to_string(&v.as_object().unwrap().iter().collect::<BTreeMap<_, _>>())
                    .unwrap()
            });
        }
        out.insert(table.to_owned(), Value::Array(list));
    }
    Value::Object(out)
}

fn scrub_report(mut report: Value) -> Value {
    for key in ["started_at", "finished_at", "duration_seconds"] {
        if report.get(key).is_some() {
            report[key] = json!("<T>");
        }
    }
    report
}

fn go_float_numbers(value: Value) -> Value {
    // Go decodes every JSON number into float64 before re-marshalling; integral
    // values print without a fraction, so integer comparison is equivalent.
    value
}

/// Runs one scenario and returns the observed value in the fixture's shape.
fn observe(case: &Value, scratch: &Path) -> Value {
    let sc = &case["scenario"];
    let id = sc["id"].as_str().unwrap();
    let _guard = ENV_LOCK.lock().unwrap_or_else(|e| e.into_inner());
    let root = std::fs::canonicalize(scratch).unwrap().join(id);
    let tmp = root.join("tmp");
    std::fs::create_dir_all(&tmp).unwrap();
    // SAFETY: serialized by ENV_LOCK; the server thread never reads it.
    unsafe { std::env::set_var("TMPDIR", &tmp) };

    let server = Server::start(routes_from(&sc["routes"]));
    let base_url = format!("http://{}", server.host);
    let norm = Norm {
        root: root.to_string_lossy().into_owned(),
        host: server.host.clone(),
        run_id: Regex::new(r"paperless-\d{8}T\d{6}\.\d{9}Z").unwrap(),
        tmp: Regex::new(r"\.tmp-\d+|symingest-import-\d+").unwrap(),
        now: Regex::new(r"(?m)^ingested_at: \S+$").unwrap(),
        eta: Regex::new(r"rate=\S+ eta=\S+").unwrap(),
    };

    let vault = root.join("vault");
    let store = Store::open(&root.join("db/docs.db")).unwrap();
    let store = Arc::new(Mutex::new(store));
    let log_buf = Arc::new(Mutex::new(String::new()));
    let mut pipeline = Pipeline::new(Arc::clone(&store), NoteWriter::new(vault.to_str().unwrap()));
    pipeline.engine = Some(Arc::new(RunEngine {
        fail_text: sc["engine"] == "fail-text",
    }));
    pipeline.archive_dir = root.join("archive").to_string_lossy().into_owned();
    {
        let log = Arc::clone(&log_buf);
        pipeline.log = Box::new(move |line| {
            let mut guard = log.lock().unwrap();
            guard.push_str(line);
            guard.push('\n');
        });
    }

    let mut runs = Vec::new();
    for spec in sc["runs"].as_array().unwrap() {
        server
            .routes
            .lock()
            .unwrap()
            .extend(routes_from(&spec["routes_after"]));
        log_buf.lock().unwrap().clear();
        let progress_buf = Arc::new(Mutex::new(String::new()));
        let stderr_buf = Arc::new(Mutex::new(String::new()));
        let sink = |buf: &Arc<Mutex<String>>| -> Sink {
            let buf = Arc::clone(buf);
            Arc::new(move |text| buf.lock().unwrap().push_str(text))
        };
        let log_sink: Sink = {
            let log = Arc::clone(&log_buf);
            Arc::new(move |line| {
                let mut guard = log.lock().unwrap();
                guard.push_str(line);
                guard.push('\n');
            })
        };
        let flag = |name: &str| spec[name].as_bool().unwrap_or(false);
        let opts = Options {
            base_url: base_url.clone(),
            token: "test-token".to_owned(),
            since: spec["since"].as_str().unwrap_or("").to_owned(),
            dry_run: flag("dry_run"),
            plan: flag("plan"),
            resume: flag("resume"),
            retry_failed: flag("retry_failed"),
            concurrency: spec["concurrency"].as_u64().unwrap_or(0) as usize,
            checkpoint_every: spec["checkpoint_every"].as_u64().unwrap_or(0) as usize,
            limit: spec["limit"].as_u64().unwrap_or(0) as usize,
            ids: spec["ids"]
                .as_array()
                .map(|a| a.iter().map(|v| v.as_i64().unwrap()).collect())
                .unwrap_or_default(),
            preserve_storage_paths: flag("preserve_storage_paths"),
            target_vault: spec["target_vault_override"]
                .as_str()
                .unwrap_or("")
                .to_owned(),
            progress: if flag("no_progress") {
                None
            } else {
                Some(sink(&progress_buf))
            },
            stderr: sink(&stderr_buf),
            log: log_sink,
            ..Options::default()
        };
        let outcome = run(&opts, &pipeline);

        let mut obs = serde_json::Map::new();
        obs.insert(
            "error".into(),
            json!(outcome.error.as_deref().map_or(String::new(), |e| norm.apply(e))),
        );
        let mut stats_value = Value::Null;
        let mut report_value = Value::Null;
        if let Some(stats) = &outcome.stats {
            let mut results = Vec::new();
            for r in &stats.results {
                let mut v = serde_json::to_value(r).unwrap();
                for key in ["vault_path", "archive_path", "import_run_id", "error", "reason"] {
                    if let Some(s) = v.get(key).and_then(Value::as_str) {
                        v[key] = json!(norm.apply(s));
                    }
                }
                if let Some(list) = v.get_mut("warnings").and_then(Value::as_array_mut) {
                    for w in list {
                        *w = json!(norm.apply(w.as_str().unwrap()));
                    }
                }
                results.push(v);
            }
            let mut warnings = stats.warnings.clone();
            if opts.concurrency > 1 {
                warnings.sort();
            }
            stats_value = json!({
                "imported": stats.imported, "skipped": stats.skipped, "failed": stats.failed,
                "total": stats.total, "warnings": warnings, "run_id": norm.apply(&stats.run_id),
                "source": stats.source, "source_url": norm.apply(&stats.source_url),
                "mode": stats.mode, "selected_ids": stats.selected_ids,
                "results": if results.is_empty() { Value::Null } else { Value::Array(results) },
                "audit": stats.audit.as_ref().map(|a| serde_json::to_value(a).unwrap()),
                "finished_after_started": stats.finished_at >= stats.started_at,
            });
            let report_path = spec["report_path"].as_str().unwrap_or("");
            if !report_path.is_empty() {
                let path = root.join(report_path);
                let report = stats.build_migration_report(flag("report_dry_run_flag"));
                match write_migration_report(path.to_str().unwrap(), &report) {
                    Ok(()) => {
                        let text = std::fs::read_to_string(&path).unwrap();
                        assert!(text.ends_with("}\n") && text.starts_with("{\n  \""), "indent");
                        let text = norm.apply(&text);
                        report_value = scrub_report(serde_json::from_str(&text).unwrap());
                    }
                    Err(e) => {
                        let prior = obs["error"].as_str().unwrap().to_owned();
                        obs.insert("error".into(), json!(format!("{prior} | report: {}", norm.apply(&e))));
                    }
                }
            }
        }
        obs.insert("stats".into(), stats_value);
        if !report_value.is_null() {
            obs.insert("report".into(), report_value);
        }
        let mut progress = sorted_lines(&norm.eta.replace_all(
            &norm.apply(&progress_buf.lock().unwrap()),
            "rate=<R> eta=<E>",
        ));
        let mut log = sorted_lines(&norm.apply(&log_buf.lock().unwrap()));
        if opts.concurrency > 1 {
            progress.sort();
            log.sort();
        }
        obs.insert("progress".into(), json!(progress));
        let mut stderr = sorted_lines(&norm.apply(&stderr_buf.lock().unwrap()));
        if opts.concurrency > 1 {
            stderr.sort();
        }
        obs.insert("stderr".into(), json!(stderr));
        obs.insert("log".into(), json!(log));
        runs.push(Value::Object(obs));
    }
    drop(pipeline);
    drop(store);
    let mut requests = server.finish();
    for r in &mut requests {
        let q = norm.apply(r["query"].as_str().unwrap());
        r["query"] = json!(q);
    }
    let unordered = sc["runs"]
        .as_array()
        .unwrap()
        .iter()
        .any(|r| r["concurrency"].as_u64().unwrap_or(0) > 1);
    if unordered {
        requests.sort_by_key(|r| {
            ["method", "path", "query", "auth"].map(|k| r[k].as_str().unwrap().to_owned())
        });
    }
    let tables = dump_tables(&root.join("db/docs.db"), &norm, unordered);
    let vault = Value::Array(snapshot(&root, "vault", &norm));
    let archive = Value::Array(snapshot(&root, "archive", &norm));
    let leaked: Vec<_> = std::fs::read_dir(&tmp).unwrap().collect();
    assert!(leaked.is_empty(), "{id}: temporary files leaked: {leaked:?}");
    json!({"runs": runs, "requests": requests, "vault": vault, "archive": archive, "tables": tables})
}

/// Field-by-field diff of two observations (first differing leaf).
fn diff(path: &str, want: &Value, got: &Value, out: &mut Vec<String>) {
    match (want, got) {
        (Value::Object(a), Value::Object(b)) => {
            for key in a.keys().chain(b.keys()).collect::<std::collections::BTreeSet<_>>() {
                diff(
                    &format!("{path}.{key}"),
                    a.get(key).unwrap_or(&Value::Null),
                    b.get(key).unwrap_or(&Value::Null),
                    out,
                );
            }
        }
        (Value::Array(a), Value::Array(b)) if a.len() == b.len() => {
            for (i, (x, y)) in a.iter().zip(b).enumerate() {
                diff(&format!("{path}[{i}]"), x, y, out);
            }
        }
        _ => {
            if go_float_numbers(want.clone()) != *got {
                out.push(format!("{path}: go {want} rust {got}"));
            }
        }
    }
}

fn compare(case: &Value, scratch: &Path) -> Vec<String> {
    let observed = observe(case, scratch);
    let mut diffs = Vec::new();
    for key in ["requests", "vault", "archive", "tables"] {
        diff(key, &case[key], &observed[key], &mut diffs);
    }
    let (want_runs, got_runs) = (
        case["runs"].as_array().unwrap(),
        observed["runs"].as_array().unwrap(),
    );
    if want_runs.len() != got_runs.len() {
        diffs.push("run count".to_owned());
    }
    for (i, (w, g)) in want_runs.iter().zip(got_runs).enumerate() {
        let mut w = w.clone();
        // Go always records a `report` only when written; absent otherwise.
        if w.get("report").is_none() {
            w.as_object_mut().unwrap().remove("report");
        }
        diff(&format!("runs[{i}]"), &w, g, &mut diffs);
    }
    diffs
}

#[test]
fn paperless_run_matches_go() {
    let fx = fixture();
    let cases = fx["cases"].as_array().unwrap();
    assert!(cases.len() >= 24, "scenarios shrank: {}", cases.len());
    let scratch = std::env::temp_dir().join(format!("paperless-run-{}", std::process::id()));
    std::fs::create_dir_all(&scratch).unwrap();
    let mut failures = Vec::new();
    let mut imported = 0;
    for case in cases {
        for run in case["runs"].as_array().unwrap() {
            imported += run["stats"]["imported"].as_u64().unwrap_or(0);
        }
        let id = case["scenario"]["id"].as_str().unwrap();
        for d in compare(case, &scratch).into_iter().take(6) {
            failures.push(format!("{id}: {d}"));
        }
    }
    let _ = std::fs::remove_dir_all(&scratch);
    assert!(imported >= 15, "oracle imported only {imported}");
    assert!(failures.is_empty(), "{} differences:\n{}", failures.len(), failures.join("\n"));
}

#[test]
fn paperless_run_negative_controls_are_caught() {
    let fx = fixture();
    let cases = fx["cases"].as_array().unwrap();
    let scratch = std::env::temp_dir().join(format!("paperless-neg-{}", std::process::id()));
    std::fs::create_dir_all(&scratch).unwrap();
    let case = cases
        .iter()
        .find(|c| c["scenario"]["id"] == "download-failure-then-retry-failed")
        .unwrap();
    assert!(compare(case, &scratch).is_empty());
    for mutate in [
        |c: &mut Value| c["runs"][0]["stats"]["failed"] = json!(7),
        |c: &mut Value| c["tables"]["paperless_import_state"][0]["status"] = json!("failed"),
        |c: &mut Value| c["vault"][1]["text"] = json!("tampered"),
        |c: &mut Value| c["requests"][0]["query"] = json!("format=xml"),
        |c: &mut Value| c["runs"][1]["progress"][0] = json!("[9/9] nope"),
    ] {
        let mut tampered = case.clone();
        mutate(&mut tampered);
        assert!(!compare(&tampered, &scratch).is_empty(), "tampering went unnoticed");
    }
    let _ = std::fs::remove_dir_all(&scratch);
}
